def can_finish(num_courses, prerequisites):
    graph = [[] for _ in range(num_courses)]
    for course, pre in prerequisites:
        graph[pre].append(course)
    state = [0] * num_courses          # 0 new, 1 on the current path, 2 done

    def has_cycle(u):
        state[u] = 1
        for v in graph[u]:
            if state[v] == 1 or (state[v] == 0 and has_cycle(v)):
                return True            # an edge back into the current path
        state[u] = 2
        return False

    return not any(state[u] == 0 and has_cycle(u) for u in range(num_courses))

