def find_order(num_courses, prerequisites):
    graph = [[] for _ in range(num_courses)]
    for course, pre in prerequisites:
        graph[pre].append(course)
    state, order = [0] * num_courses, []   # 0 new, 1 on the path, 2 done

    def dfs(u):
        state[u] = 1
        for v in graph[u]:
            if state[v] == 1 or (state[v] == 0 and not dfs(v)):
                return False           # cycle
        state[u] = 2
        order.append(u)                # finishes after every course that needs it
        return True

    if all(state[u] or dfs(u) for u in range(num_courses)):
        return order[::-1]             # reverse post-order
    return []
